<?php
require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/auth.php';require_login();
$rows=$pdo->query("SELECT p.sku,p.name,c.name category_name,p.price,p.stock,p.minimum_stock,COALESCE(SUM(CASE WHEN sm.type='IN' THEN sm.quantity ELSE 0 END),0) total_in,COALESCE(SUM(CASE WHEN sm.type='OUT' THEN sm.quantity ELSE 0 END),0) total_out FROM products p JOIN categories c ON c.id=p.category_id LEFT JOIN stock_movements sm ON sm.product_id=p.id GROUP BY p.id,p.sku,p.name,c.name,p.price,p.stock,p.minimum_stock ORDER BY p.name")->fetchAll();
$in=(int)$pdo->query("SELECT COALESCE(SUM(quantity),0) FROM stock_movements WHERE type='IN'")->fetchColumn();$out=(int)$pdo->query("SELECT COALESCE(SUM(quantity),0) FROM stock_movements WHERE type='OUT'")->fetchColumn();$pageTitle='Laporan Stok';include __DIR__.'/includes/header.php';?>
<div class="stats"><div class="stat-card"><div class="stat-top">Total barang masuk</div><div class="stat-number"><?= number_format($in) ?></div><div class="stat-foot">Unit tercatat</div></div><div class="stat-card"><div class="stat-top">Total barang keluar</div><div class="stat-number"><?= number_format($out) ?></div><div class="stat-foot">Unit tercatat</div></div><div class="stat-card"><div class="stat-top">Jumlah produk</div><div class="stat-number"><?= count($rows) ?></div><div class="stat-foot">SKU terdaftar</div></div><div class="stat-card"><div class="stat-top">Nilai persediaan</div><div class="stat-number" style="font-size:22px">Rp <?= number_format(array_sum(array_map(fn($r)=>(float)$r['price']*(int)$r['stock'],$rows)),0,',','.') ?></div><div class="stat-foot">Stok × harga produk</div></div></div>
<section class="panel"><div class="panel-head"><div><h2>Laporan Inventory</h2><p>Ringkasan stok dan histori kuantitas per SKU</p></div><button class="btn secondary" onclick="window.print()">Cetak laporan</button></div><div class="table-wrap"><table><thead><tr><th>SKU</th><th>PRODUK</th><th>KATEGORI</th><th>MASUK</th><th>KELUAR</th><th>STOK AKHIR</th><th>STATUS</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= h($r['sku']) ?></td><td class="product-name"><?= h($r['name']) ?></td><td><?= h($r['category_name']) ?></td><td><span class="badge green"><?= (int)$r['total_in'] ?></span></td><td><span class="badge purple"><?= (int)$r['total_out'] ?></span></td><td><b><?= (int)$r['stock'] ?></b></td><td><span class="badge <?= $r['stock']<=$r['minimum_stock']?'orange':'green' ?>"><?= $r['stock']<=$r['minimum_stock']?'Stok rendah':'Aman' ?></span></td></tr><?php endforeach; ?></tbody></table></div><p class="muted">Rumus stok akhir: stok awal + total barang masuk − total barang keluar. Nilai stok pada tabel produk menjadi saldo berjalan yang diperbarui oleh transaksi.</p></section>
<?php include __DIR__.'/includes/footer.php';?>